using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using MyExpenseTracker.Api.Data;using MyExpenseTracker.Api.Models;namespace MyExpenseTracker.Api.Controllers;[Authorize,ApiController,Route("api/transactions")]public class TransactionsController(AppDbContext db):ControllerBase{public static readonly string[] E={"Food","Entertainment","Shopping","Travel","Home","Medicines","Movies","Mobile Recharge","Gaming","Flight Booking","Subscriptions","Electricity","EMIs","Other"};public static readonly string[] I={"Salary","Gift","Bonus","Other"};[HttpGet]public async Task<IActionResult> Get()=>Ok(await db.Transactions.Include(x=>x.Account).OrderByDescending(x=>x.TransactionDate).ThenByDescending(x=>x.Id).ToListAsync());[HttpPost]public async Task<IActionResult>Add(Transaction x){if(x.Amount<=0||string.IsNullOrWhiteSpace(x.Description)||!await db.Accounts.AnyAsync(a=>a.Id==x.AccountId))return BadRequest();if(!(x.Kind==TransactionKind.Expense?E:I).Contains(x.Category))return BadRequest();x.Id=0;x.Description=x.Description.Trim();db.Transactions.Add(x);await db.SaveChangesAsync();return Ok(x);}[HttpPut("{id:int}")]public async Task<IActionResult>Edit(int id,Transaction x){var t=await db.Transactions.FindAsync(id);if(t==null)return NotFound();if(x.Amount<=0||string.IsNullOrWhiteSpace(x.Description)||!await db.Accounts.AnyAsync(a=>a.Id==x.AccountId))return BadRequest();t.AccountId=x.AccountId;t.Kind=x.Kind;t.TransactionDate=x.TransactionDate;t.Amount=x.Amount;t.Category=x.Category;t.Description=x.Description.Trim();await db.SaveChangesAsync();return Ok(t);}[HttpDelete("{id:int}")]public async Task<IActionResult>Delete(int id){var t=await db.Transactions.FindAsync(id);if(t==null)return NotFound();db.Transactions.Remove(t);await db.SaveChangesAsync();return NoContent();}}